// Package reserved holds the extension names DuckDB owns (spec 0008): core names from the DuckDB
// pin, community names from duckdb/community-extensions at a pinned commit, and a curated extra list.
// The lists are generated by `make reserved` and only ever grow: a name that was reserved stays
// reserved, since clients may have installed it.
package reserved

import (
	_ "embed"
	"strings"
)

// Kinds of reserved names.
const (
	Core      = "core"
	Community = "community"
)

var (
	//go:embed core.txt
	coreList string
	//go:embed community.txt
	communityList string
	//go:embed extra.txt
	extraList string

	kinds = load()
)

func load() map[string]string {
	m := map[string]string{}
	for kind, list := range map[string]string{Community: communityList, Core: coreList + "\n" + extraList} {
		for _, line := range strings.Split(list, "\n") {
			if n := strings.TrimSpace(line); n != "" && !strings.HasPrefix(n, "#") {
				if m[n] != Core { // a name in both lists is core
					m[n] = kind
				}
			}
		}
	}
	return m
}

// Kind returns core or community for a reserved name, and "" for any other.
func Kind(name string) string { return kinds[name] }

//go:embed aliases.txt
var aliasList string

var aliases = loadAliases()

func loadAliases() map[string]string {
	m := map[string]string{}
	for _, line := range strings.Split(aliasList, "\n") {
		if f := strings.Fields(line); len(f) == 2 && !strings.HasPrefix(f[0], "#") {
			m[f[0]] = f[1]
		}
	}
	return m
}

// Canonical returns the name DuckDB installs an alias as (postgres: postgres_scanner), and "" for a
// name that is not an alias (spec 0009).
func Canonical(name string) string { return aliases[name] }
